begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(12);
create temp table f as select gen_random_uuid() u,gen_random_uuid() other,gen_random_uuid() s,gen_random_uuid() q,gen_random_uuid() a,gen_random_uuid() object,gen_random_uuid() speaking,gen_random_uuid() attempt;
grant select on f to authenticated;
insert into auth.users(id,email) select u,'wav-owner@example.invalid' from f;
insert into auth.users(id,email) select other,'wav-other@example.invalid' from f;
select set_config('request.jwt.claim.sub',(select u::text from f),true);
select public.create_reserved_interview(s,'Engineer','standard','intermediate','balanced',jsonb_build_array(jsonb_build_object('id',q,'text','Synthetic question'))) from f;
select public.start_interview_session(s) from f;
insert into public.interview_answers(id,user_id,session_id,question_id) select a,u,s,q from f;
insert into public.speaking_sessions(id,user_id,category,prompt_id,prompt_text,difficulty,time_limit_seconds) select speaking,u,'everyday','synthetic','Describe a synthetic day','warm_up',60 from f;
select ok((select 'audio/wav'=any(allowed_mime_types) from storage.buckets where id='interview-audio'),'WAV enabled for private interview bucket');
set local role authenticated;
select lives_ok($$insert into storage.objects(bucket_id,name,owner_id,metadata) select 'interview-audio',u||'/'||s||'/'||a||'/'||object||'.wav',u::text,'{"size":32044,"mimetype":"audio/wav"}' from f$$,'owner can upload WAV in authorized answer folder');
select lives_ok($$select public.attach_answer_audio(a,u||'/'||s||'/'||a||'/'||object||'.wav',1,'audio/wav',32044) from f$$,'owner attaches valid WAV metadata');
select lives_ok($$select public.attach_answer_audio(a,u||'/'||s||'/'||a||'/'||object||'.wav',1,'audio/wav',32044) from f$$,'duplicate attachment reuses saved recording');
select is((select audio_generation from public.interview_answers where id=(select a from f)),1,'duplicate WAV attachment does not create a new audio generation');
select throws_ok($$select public.attach_answer_audio(a,u||'/'||s||'/'||a||'/'||object||'.wav',1,'audio/mp4',32044) from f$$,'22023','Audio extension and MIME disagree','renaming cannot bypass MIME validation');
select lives_ok($$select public.reserve_speaking_attempt(attempt,speaking,u) from f$$,'speaking reservation admitted');
select lives_ok($$select public.reserve_speaking_attempt(attempt,speaking,u) from f$$,'lost reservation response retries same attempt');
select is((select count(*)::integer from public.speaking_attempts),1,'duplicate reservation spends one attempt');
select lives_ok($$insert into storage.objects(bucket_id,name,owner_id,metadata) select 'speaking-audio',u||'/'||speaking||'/'||attempt||'.wav',u::text,'{"size":32044,"mimetype":"audio/wav"}' from f$$,'speaking WAV uses the authorized three-part path');
select lives_ok($$select public.attach_speaking_audio(attempt,u||'/'||speaking||'/'||attempt||'.wav',1,'audio/wav',32044) from f$$,'speaking WAV attachment accepted');
reset role;
select set_config('request.jwt.claim.sub',(select other::text from f),true);
set local role authenticated;
select is((select count(*)::integer from storage.objects where bucket_id in ('interview-audio','speaking-audio')),0,'another user cannot read either private WAV');
select * from finish();
rollback;
